def _handoff_labeler_route_authorization_fields(handoff: Mapping[str, object]) -> dict[str, object]:
    policy = (
        handoff.get("labeler_route_authorization_policy")
        if isinstance(handoff.get("labeler_route_authorization_policy"), Mapping)
        else None
    )
    checklist = (
        handoff.get("labeler_route_authorization_checklist")
        if isinstance(handoff.get("labeler_route_authorization_checklist"), Mapping)
        else None
    )
    contract = _labeler_route_authorization_contract_policy(policy or {})
    present = policy is not None
    runtime_checklist_present = checklist is not None
    runtime_checklist_ready = bool((checklist or {}).get("ready"))
    single_owner_store_proof_required = bool(
        contract.get("single_owner_store_proof_required_for_browser_work")
    )
    single_owner_store_proof_ready = bool(
        (checklist or {}).get("single_owner_store_proof_ready")
    )
    assignment_ownership_integrity_ok = bool(
        (checklist or {}).get("assignment_ownership_integrity_ok")
    )
    duplicate_active_owner_count = int(
        (checklist or {}).get("duplicate_active_owner_count") or 0
    )
    browser_mutation_target_resolved_server_side = bool(
        (checklist or {}).get("browser_mutation_target_resolved_server_side")
    )
    labelers_mutate_assigned_training_zarrs = bool(
        (checklist or {}).get("labelers_mutate_assigned_training_zarrs")
    )
    labelers_mutate_intermediate_csvs = bool(
        (checklist or {}).get("labelers_mutate_intermediate_csvs")
    )
    runtime_store_proof_ready = (
        not single_owner_store_proof_required
        or (
            runtime_checklist_present
            and single_owner_store_proof_ready
            and assignment_ownership_integrity_ok
            and duplicate_active_owner_count == 0
            and browser_mutation_target_resolved_server_side
            and labelers_mutate_assigned_training_zarrs
            and not labelers_mutate_intermediate_csvs
        )
    )
    ready = present and bool(contract.get("ready")) and runtime_store_proof_ready
    if ready:
        readiness = "passed"
        action = ""
    elif not present:
        readiness = "missing_policy"
        action = "Regenerate the handoff so labeler-route authorization policy metadata is present before sharing links."
    else:
        readiness = "needs_review"
        action = (
            "Regenerate or repair the handoff so copied queue, dashboard, and signed task links require "
            "resolved identity, expected-user match, known assignment-store user, active assignment, "
            "startable task-state checks, single-owner store proof, assignment-integrity OK, zero duplicate "
            "active owners, runtime operator-validation start-gate rechecks for signed links, "
            "server-resolved training-Zarr targets, and no intermediate CSV mutation; "
            "the runtime route authorization checklist must include single_owner_store_proof_ready=true, "
            "assignment_ownership_integrity_ok=true, browser_mutation_target_resolved_server_side=true, "
            "labelers_mutate_assigned_training_zarrs=true, "
            "forwarded_signed_links_recheck_runtime_operator_validation_start_gate=true, and "
            "labelers_mutate_intermediate_csvs=false."
        )
    fields = {
        "labeler_route_authorization_policy_present": present,
        "labeler_route_authorization_ready": ready,
        "labeler_route_authorization_readiness": readiness,
        "labeler_route_authorization_operator_action": action,
        "labeler_route_authorization_expected_user_match_required": bool(
            contract.get("expected_user_must_match_resolved_user")
        ),
        "labeler_route_authorization_known_user_required": bool(
            contract.get("known_assignment_store_user_required")
        ),
        "labeler_route_authorization_active_assignment_required": bool(
            contract.get("task_open_requires_active_assignment")
        ),
        "labeler_route_authorization_task_open_requires_active_assignment": bool(
            contract.get("task_open_requires_active_assignment")
        ),
        "labeler_route_authorization_task_open_requires_startable_task_state": bool(
            contract.get("task_open_requires_startable_task_state")
        ),
        "labeler_route_authorization_startable_task_states": json.dumps(
            contract.get("startable_task_states") or []
        ),
        "labeler_route_authorization_signed_links_are_entry_hints": bool(
            contract.get("signed_links_are_entry_hints_not_authorization")
        ),
        "labeler_route_authorization_signed_links_recheck_runtime_start_gate": bool(
            contract.get("forwarded_signed_links_recheck_runtime_operator_validation_start_gate")
        ),
        "labeler_route_authorization_forwarded_links_rechecked": bool(
            contract.get("copied_links_rechecked_server_side")
        ),
        "labeler_route_authorization_runtime_checklist_present": runtime_checklist_present,
        "labeler_route_authorization_runtime_checklist_ready": runtime_checklist_ready,
        "labeler_route_authorization_single_owner_store_proof_ready": (
            single_owner_store_proof_ready
        ),
        "labeler_route_authorization_assignment_ownership_integrity_ok": (
            assignment_ownership_integrity_ok
        ),
        "labeler_route_authorization_duplicate_active_owner_count": (
            duplicate_active_owner_count
        ),
        "labeler_route_authorization_browser_mutation_target_resolved_server_side": (
            browser_mutation_target_resolved_server_side
        ),
        "labeler_route_authorization_labelers_mutate_assigned_training_zarrs": (
            labelers_mutate_assigned_training_zarrs
        ),
        "labeler_route_authorization_labelers_mutate_intermediate_csvs": (
            labelers_mutate_intermediate_csvs
        ),
        "labeler_route_authorization_single_owner_store_proof_required_for_browser_work": bool(
            contract.get("single_owner_store_proof_required_for_browser_work")
        ),
        "labeler_route_authorization_single_owner_store_proof_requires_integrity_ok": bool(
            contract.get("single_owner_store_proof_requires_integrity_ok")
        ),
        "labeler_route_authorization_single_owner_store_proof_requires_zero_duplicate_active_owners": bool(
            contract.get("single_owner_store_proof_requires_zero_duplicate_active_owners")
        ),
        "labeler_route_authorization_single_owner_store_proof_requires_training_zarr_target": bool(
            contract.get("single_owner_store_proof_requires_training_zarr_target")
        ),
        "labeler_route_authorization_single_owner_store_proof_rejects_intermediate_csv_mutation": bool(
            contract.get("single_owner_store_proof_rejects_intermediate_csv_mutation")
        ),
    }
    if not runtime_checklist_present:
        for key in list(fields):
            if key in handoff:
                fields[key] = handoff[key]
    return fields




def _handoff_no_open_task_message(recording: Mapping[str, object]) -> str:
    message = str(recording.get("no_open_task_message") or "").strip()
    if message:
        return message
    total = int(recording.get("total_task_count") or 0)
    complete = int(recording.get("complete_task_count") or 0)
    if total > 0 and complete >= total:
        return "All tasks for this recording are complete. Ask the operator before reopening or continuing work."
    if total > 0:
        return "This recording is assigned to you, but no startable tasks are included in this handoff. Ask the operator to inspect the batch if you expected work here."
    return "This recording is assigned to you, but no browser-labeling tasks have been generated yet. Ask the operator to generate tasks or inspect the batch if you expected work here."








def _sum_recordings_without_open_tasks_by_reason(manifests: Sequence[Mapping[str, object]]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for manifest in manifests:
        manifest_counts = manifest.get("counts") if isinstance(manifest.get("counts"), Mapping) else {}
        by_reason = (
            manifest_counts.get("recordings_without_open_tasks_by_reason")
            if isinstance(manifest_counts, Mapping)
            else None
        )
        if isinstance(by_reason, Mapping):
            for reason, value in by_reason.items():
                reason_text = str(reason or "unknown").strip() or "unknown"
                counts[reason_text] = counts.get(reason_text, 0) + int(value or 0)
            continue
        unknown_count = int(manifest_counts.get("recordings_without_open_tasks") or 0) if isinstance(manifest_counts, Mapping) else 0
        if unknown_count:
            counts["unknown"] = counts.get("unknown", 0) + unknown_count
    return dict(sorted(counts.items()))


def _sum_handoff_progress_summary(manifests: Sequence[Mapping[str, object]]) -> dict[str, object]:
    summary = {
        "recording_count": 0,
        "open_task_count": 0,
        "total_task_count": 0,
        "complete_task_count": 0,
        "incomplete_task_count": 0,
        "startable_task_count": 0,
        "non_startable_task_count": 0,
        "waiting_recording_count": 0,
        "complete_recording_count": 0,
        "blocked_recording_count": 0,
        "blocked_recordings_by_reason": {},
    }
    blocked_by_reason: dict[str, int] = {}
    for manifest in manifests:
        progress = manifest.get("progress_summary") if isinstance(manifest.get("progress_summary"), Mapping) else {}
        for key in (
            "recording_count",
            "open_task_count",
            "total_task_count",
            "complete_task_count",
            "incomplete_task_count",
            "startable_task_count",
            "non_startable_task_count",
            "waiting_recording_count",
            "complete_recording_count",
            "blocked_recording_count",
        ):
            summary[key] = int(summary[key]) + int(progress.get(key) or 0)
        by_reason = progress.get("blocked_recordings_by_reason") if isinstance(progress, Mapping) else {}
        if isinstance(by_reason, Mapping):
            for reason, value in by_reason.items():
                reason_text = str(reason or "unknown").strip() or "unknown"
                blocked_by_reason[reason_text] = blocked_by_reason.get(reason_text, 0) + int(value or 0)
    summary["blocked_recordings_by_reason"] = dict(sorted(blocked_by_reason.items()))
    return summary


def _sum_handoff_dataset_queue_summary(manifests: Sequence[Mapping[str, object]]) -> dict[str, object]:
    dataset_count = 0
    waiting_dataset_count = 0
    open_task_count = 0
    non_startable_task_count = 0
    complete_task_count = 0
    task_count = 0
    dataset_ids: list[str] = []
    for manifest in manifests:
        summary = manifest.get("dataset_queue_summary") if isinstance(manifest.get("dataset_queue_summary"), Mapping) else {}
        dataset_count += int(summary.get("dataset_count") or 0)
        waiting_dataset_count += int(summary.get("waiting_dataset_count") or 0)
        open_task_count += int(summary.get("open_task_count") or 0)
        non_startable_task_count += int(summary.get("non_startable_task_count") or 0)
        complete_task_count += int(summary.get("complete_task_count") or 0)
        task_count += int(summary.get("task_count") or 0)
        ids = summary.get("dataset_ids") if isinstance(summary.get("dataset_ids"), list) else []
        dataset_ids.extend(str(dataset_id) for dataset_id in ids if str(dataset_id).strip())
    return {
        "dataset_count": dataset_count,
        "waiting_dataset_count": waiting_dataset_count,
        "open_task_count": open_task_count,
        "non_startable_task_count": non_startable_task_count,
        "complete_task_count": complete_task_count,
        "task_count": task_count,
        "dataset_ids": dataset_ids,
    }




def _count_redacted_summary_fields(value: object) -> int:
    if isinstance(value, Mapping):
        count = 0
        redacted_fields = value.get("redacted_fields")
        if isinstance(redacted_fields, list):
            count += len(redacted_fields)
        for key, item in value.items():
            if key == "redacted_fields":
                continue
            count += _count_redacted_summary_fields(item)
        return count
    if isinstance(value, list):
        return sum(_count_redacted_summary_fields(item) for item in value)
    return 0


def _handoff_sendability_reasons(manifest: Mapping[str, object]) -> list[str]:
    counts = manifest.get("counts") if isinstance(manifest.get("counts"), Mapping) else {}
    base_url_present = bool(str(manifest.get("base_url") or "").strip())
    reasons: list[str] = []
    known_user_fields = _handoff_known_user_status_fields(manifest)
    if not bool(known_user_fields["known_user_status_present"]):
        reasons.append("known_user_status_missing")
    elif not bool(known_user_fields["known_labeler"]):
        reasons.append("unknown_labeling_user")
    elif int(known_user_fields["known_user_active_assignment_count"]) <= 0:
        reasons.append("no_active_assignment")
    ownership_fields = _handoff_assignment_ownership_fields(manifest)
    if not bool(ownership_fields["assignment_ownership_evidence_present"]):
        reasons.append("assignment_ownership_missing")
    elif not bool(ownership_fields["assignment_ownership_ok"]):
        reasons.append("assignment_ownership_conflict")
    elif not bool(ownership_fields["assignment_ownership_contract_ready"]):
        reasons.append("assignment_ownership_contract_not_ready")
    entry_fields = _handoff_entry_artifact_fields(manifest)
    if base_url_present and not bool(entry_fields["preferred_labeler_entry_url_matches_personal_dataset_queue"]):
        reasons.append("preferred_personal_queue_mismatch")
    labeler_safety_fields = _handoff_labeler_safety_fields(manifest)
    if not bool(labeler_safety_fields["labeler_safety_policy_present"]):
        reasons.append("labeler_safety_policy_missing")
    elif not bool(labeler_safety_fields["labeler_safety_ready"]):
        reasons.append("labeler_safety_policy_not_ready")
    route_authorization_fields = _handoff_labeler_route_authorization_fields(manifest)
    if not bool(route_authorization_fields["labeler_route_authorization_policy_present"]):
        reasons.append("labeler_route_authorization_policy_missing")
    elif not bool(route_authorization_fields["labeler_route_authorization_ready"]):
        reasons.append("labeler_route_authorization_policy_not_ready")
    signed_link_fields = _handoff_signed_link_policy_fields(manifest)
    if not bool(signed_link_fields["signed_link_policy_present"]):
        reasons.append("signed_link_policy_missing")
    elif not bool(signed_link_fields["signed_link_policy_ready"]):
        reasons.append("signed_link_policy_not_ready")
    session_guard_fields = _handoff_session_guard_fields(manifest)
    if not bool(session_guard_fields["session_guard_policy_present"]):
        reasons.append("session_guard_policy_missing")
    elif not bool(session_guard_fields["session_guard_policy_ready"]):
        reasons.append("session_guard_policy_not_ready")
    task_state_fields = _handoff_task_state_policy_fields(manifest)
    if not bool(task_state_fields["task_state_policy_present"]):
        reasons.append("task_state_policy_missing")
    elif not bool(task_state_fields["task_state_policy_ready"]):
        reasons.append("task_state_policy_not_ready")
    zarr_backup_fields = _handoff_zarr_backup_fields(manifest)
    if not bool(zarr_backup_fields["zarr_backup_policy_present"]):
        reasons.append("zarr_backup_policy_missing")
    elif not bool(zarr_backup_fields["zarr_backup_ready"]):
        reasons.append("zarr_backup_policy_not_ready")
    mutation_audit_fields = _handoff_mutation_audit_fields(manifest)
    if not bool(mutation_audit_fields["mutation_audit_policy_present"]):
        reasons.append("mutation_audit_policy_missing")
    elif not bool(mutation_audit_fields["mutation_audit_ready"]):
        reasons.append("mutation_audit_policy_not_ready")
    response_security_fields = _handoff_browser_response_security_fields(manifest)
    if not bool(response_security_fields["browser_response_security_policy_present"]):
        reasons.append("browser_response_security_policy_missing")
    elif not bool(response_security_fields["browser_response_security_ready"]):
        reasons.append("browser_response_security_policy_not_ready")
    mutation_write_fields = _handoff_browser_mutation_write_fields(manifest)
    if not bool(mutation_write_fields["browser_mutation_write_policy_present"]):
        reasons.append("browser_mutation_write_policy_missing")
    elif not bool(mutation_write_fields["browser_mutation_write_ready"]):
        reasons.append("browser_mutation_write_policy_not_ready")
    store_consistency = (
        manifest.get("store_consistency")
        if isinstance(manifest.get("store_consistency"), Mapping)
        else {}
    )
    reassignment_session_safety = manifest.get("reassignment_session_safety")
    if not isinstance(reassignment_session_safety, Mapping):
        reassignment_session_safety = (
            store_consistency.get("reassignment_session_safety")
            if isinstance(store_consistency.get("reassignment_session_safety"), Mapping)
            else {}
        )
    if reassignment_session_safety and not bool(reassignment_session_safety.get("ok")):
        reasons.append("reassignment_session_safety_failed")
    if not bool(manifest.get("ok")):
        reasons.append("store_check_failed")
    if int(counts.get("tasks") or 0) <= 0:
        reasons.append("no_tasks")
    if int(counts.get("signed_links") or 0) <= 0:
        reasons.append("no_signed_links")
    if not base_url_present:
        reasons.append("missing_base_url")
    elif int(counts.get("signed_links") or 0) > 0 and int(counts.get("ready_to_share_links") or 0) <= 0:
        reasons.append("no_ready_to_share_links")
    if base_url_present:
        guarded_link_reasons = {
            "expected_user_labeler_landing_url": "missing_guarded_landing_url",
            "expected_user_dataset_queue_url": "missing_guarded_dataset_queue_url",
            "expected_user_dashboard_url": "missing_guarded_dashboard_url",
            "expected_user_identity_probe_url": "missing_guarded_identity_probe_url",
        }
        for key in entry_fields["missing_guarded_links"]:
            reason = guarded_link_reasons.get(str(key))
            if reason:
                reasons.append(reason)
    artifact_reasons = {
        "html_index": "missing_handoff_index_artifact",
        "message": "missing_message_artifact",
        "quickstart": "missing_quickstart_artifact",
        "dataset_queue": "missing_dataset_queue_artifact",
        "manifest": "missing_handoff_manifest_artifact",
    }
    for key in entry_fields["missing_handoff_artifacts"]:
        reason = artifact_reasons.get(str(key))
        if reason:
            reasons.append(reason)
    if _handoff_dataset_queue_blocks_labeler_start(manifest):
        reasons.append("dataset_queue_blocks_labeler_start")
    if bool(manifest.get("operator_validation_required_before_invite")) and not bool(
        manifest.get("operator_validation_all_complete")
    ):
        needs_review_gate_ids = (
            manifest.get("operator_validation_needs_review_gate_ids")
            if isinstance(manifest.get("operator_validation_needs_review_gate_ids"), list)
            else []
        )
        reasons.append("operator_validation_needs_review" if needs_review_gate_ids else "operator_validation_pending")
    return reasons


