def _write_user_handoff_html_index(
    *,
    user: str,
    work: dict[str, object],
    links: list[dict[str, object]],
    manifest: dict[str, object],
    output_path: Path,
) -> None:
    links_by_task_id = {str(link.get("task_id") or ""): link for link in links}
    base_url = str(manifest.get("base_url") or "").rstrip("/")
    landing_url = str(manifest.get("expected_user_labeler_landing_url") or manifest.get("labeler_landing_url") or base_url).strip()
    dashboard_url = str(manifest.get("expected_user_dashboard_url") or _dashboard_url_for_base(base_url))
    dataset_queue_url = str(manifest.get("expected_user_dataset_queue_url") or manifest.get("dataset_queue_url") or "").strip()
    labeling_home_url = str(
        manifest.get("expected_user_labeling_home_url")
        or manifest.get("labeling_home_url")
        or ""
    ).strip()
    personalized_entry_url = str(
        manifest.get("personalized_labeler_entry_url")
        or manifest.get("expected_user_personal_dataset_queue_url")
        or ""
    ).strip()
    identity_probe_url = str(manifest.get("expected_user_identity_probe_url") or "").strip()
    has_absolute_base_url = bool(base_url)
    ready_to_send = bool(manifest.get("ready_to_send"))
    progress = (
        manifest.get("progress_summary")
        if isinstance(manifest.get("progress_summary"), Mapping)
        else work.get("progress_summary")
        if isinstance(work.get("progress_summary"), Mapping)
        else {}
    )
    dataset_queue_state = (
        manifest.get("dataset_queue_state")
        if isinstance(manifest.get("dataset_queue_state"), Mapping)
        else {}
    )
    dataset_queue_state_code = str(dataset_queue_state.get("code") or "")
    dataset_queue_state_title = str(dataset_queue_state.get("title") or "")
    dataset_queue_state_message = str(dataset_queue_state.get("message") or "")
    dataset_queue_operator_action = str(dataset_queue_state.get("operator_action") or "")
    dataset_queue_blocks_start = bool(dataset_queue_state.get("blocks_labeler_start"))
    warning_reasons: list[str] = []
    warnings = manifest.get("sendability_warnings")
    if isinstance(warnings, list):
        for warning in warnings:
            if not isinstance(warning, Mapping):
                continue
            reasons = warning.get("reasons")
            if not isinstance(reasons, list):
                continue
            for reason in reasons:
                reason_text = str(reason or "").strip()
                if reason_text and reason_text not in warning_reasons:
                    warning_reasons.append(reason_text)
    warning_reason_text = ", ".join(warning_reasons) if warning_reasons else "operator_review_required"
    sendability_actions = [
        str(action).strip()
        for action in (manifest.get("sendability_actions") if isinstance(manifest.get("sendability_actions"), list) else [])
        if str(action).strip()
    ]
    sendability_action_text = " ".join(sendability_actions)
    dashboard_entry = (
        f'<a href="{_html_escape(dashboard_url)}">{"Open" if ready_to_send else "Preview"} your personalized dashboard</a>'
        if dashboard_url
        else "This handoff was generated without a service URL. Use this page to preview assigned work, then ask the operator for the dashboard URL before opening tasks."
    )
    dataset_queue_entry = (
        f'<a href="{_html_escape(personalized_entry_url or dataset_queue_url)}">{"Open" if ready_to_send else "Preview"} your personalized dataset queue</a>'
        if personalized_entry_url or dataset_queue_url
        else ""
    )
    canonical_dataset_queue_entry = (
        f'<a href="{_html_escape(dataset_queue_url)}">Canonical dataset queue fallback</a>'
        if dataset_queue_url
        else ""
    )
    labeling_home_entry = (
        f'<a href="{_html_escape(labeling_home_url)}">Human-readable labeling home alias</a>'
        if labeling_home_url
        else ""
    )
    landing_entry = (
        f'<a href="{_html_escape(landing_url)}">{"Open" if ready_to_send else "Preview"} your datasets-waiting landing page</a>'
        if landing_url
        else ""
    )
    quickstart_class = "quickstart" if ready_to_send else "quickstart warn"
    quickstart_heading = "Before you start" if ready_to_send else "Wait for operator review"
    start_guidance = (
        "No Palette or Crimson installation is needed. Work from this browser page or the personalized dashboard."
        if ready_to_send
        else "No Palette or Crimson installation is needed. Use this page only to preview assigned work until the operator confirms this handoff is ready."
    )
    readiness_notice = (
        ""
        if ready_to_send
        else (
            f"<p><b>This handoff is not ready to start.</b> Do not open or save task work until the operator clears it. Review reasons: {_html_escape(warning_reason_text)}.</p>"
            + (
                f"<p><b>Operator repair action:</b> {_html_escape(sendability_action_text)}</p>"
                if sendability_action_text
                else ""
            )
        )
    )
    dataset_queue_state_notice = (
        f"<p><b>Dataset queue state:</b> {_html_escape(dataset_queue_state_code or 'unknown')}"
        f"{' - ' + _html_escape(dataset_queue_state_title) if dataset_queue_state_title else ''}. "
        f"Labeler start {'blocked' if dataset_queue_blocks_start else 'allowed'}.</p>"
        + (
            f"<p>{_html_escape(dataset_queue_state_message)}</p>"
            if dataset_queue_state_message
            else ""
        )
        + (
            "<p><b>Do not start new labeling from this queue until the operator resolves this state.</b></p>"
            if dataset_queue_blocks_start
            else ""
        )
        + (
            f"<p><b>Operator action:</b> {_html_escape(dataset_queue_operator_action)}</p>"
            if dataset_queue_operator_action
            else ""
        )
    )
    def task_priority(task: Mapping[str, object]) -> float:
        try:
            return float(task.get("priority") or 0)
        except (TypeError, ValueError):
            return 0.0

    rows: list[str] = []
    for recording in work.get("recordings", []):
        if not isinstance(recording, dict):
            continue
        recording_id = recording.get("recording_id", "")
        assignment_notes = recording.get("assignment_notes") or ""
        tasks = [task for task in recording.get("tasks", []) if isinstance(task, dict)]
        tasks.sort(
            key=lambda task: (
                -task_priority(task),
                str(task.get("title") or task.get("task_id") or ""),
                str(task.get("task_id") or ""),
            )
        )
        if not tasks:
            rows.append(
                "      <tr>"
                f"<td>{_html_escape(recording_id)}</td>"
                "<td></td>"
                "<td></td>"
                f"<td><span class=\"muted\">{_html_escape(_handoff_no_open_task_message(recording))}</span></td>"
                "<td></td>"
                f"<td>{_html_escape(assignment_notes)}</td>"
                "<td><span class=\"muted\">No open signed task link</span></td>"
                "</tr>"
            )
            continue
        for task in tasks:
            task_id = str(task.get("task_id") or "")
            link = links_by_task_id.get(task_id)
            url = str((link or {}).get("url") or "")
            path = str((link or {}).get("path") or "")
            title = str(task.get("title") or task_id)
            priority = task.get("priority")
            task_notes = str(task.get("notes") or "")
            task_cell = _html_escape(title)
            if task_notes:
                task_cell += f"<div class=\"task-note\"><b>Task note:</b> {_html_escape(task_notes)}</div>"
            link_ready = bool((link or {}).get("ready_to_share"))
            link_warnings = [
                str(warning.get("code") or "").strip()
                for warning in ((link or {}).get("shareability_warnings") or [])
                if isinstance(warning, Mapping) and str(warning.get("code") or "").strip()
            ]
            link_warning_text = ", ".join(link_warnings) if link_warnings else "not_ready_to_share"
            link_cell = (
                f"<a class=\"open-link\" href=\"{_html_escape(url)}\">Open task</a>"
                if url and has_absolute_base_url and link_ready
                else (
                    f"<span class=\"muted\">Not ready to open: {_html_escape(link_warning_text)}</span>"
                    if url and has_absolute_base_url
                    else (
                        f"<span class=\"muted\">Needs service URL: {_html_escape(path or url)}</span>"
                        if url
                        else "<span class=\"muted\">No active signed link</span>"
                    )
                )
            )
            rows.append(
                "      <tr>"
                f"<td>{_html_escape(recording_id)}</td>"
                f"<td>{_html_escape(task.get('workflow_kind', ''))}</td>"
                f"<td>{_html_escape(priority if priority is not None else '')}</td>"
                f"<td>{task_cell}</td>"
                f"<td>{_html_escape(task.get('state', ''))}</td>"
                f"<td>{_html_escape(assignment_notes)}</td>"
                f"<td>{link_cell}</td>"
                "</tr>"
            )
    generated_rows = "\n".join(rows) or "      <tr><td colspan=\"7\">No tasks are currently assigned.</td></tr>"
    html = f"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Palette labeling work for {_html_escape(user)}</title>
  <style>
    :root {{
      color-scheme: light;
      --ink: #1f251d;
      --muted: #647063;
      --paper: #fffdf7;
      --line: #ddd4be;
      --accent: #115c55;
      --accent-bg: #dceee8;
      --warn: #a74818;
    }}
    body {{
      margin: 0;
      background:
        linear-gradient(135deg, rgba(17, 92, 85, .10), transparent 30rem),
        radial-gradient(circle at 85% 10%, rgba(210, 128, 62, .16), transparent 22rem),
        var(--paper);
      color: var(--ink);
      font-family: "Aptos", "Segoe UI", sans-serif;
    }}
    main {{
      max-width: 76rem;
      margin: 0 auto;
      padding: 3rem 1.25rem;
    }}
    h1 {{
      margin: 0;
      font-size: clamp(2rem, 6vw, 4.5rem);
      line-height: .95;
      letter-spacing: -.045em;
    }}
    .meta {{
      margin: .9rem 0 2rem;
      color: var(--muted);
      max-width: 46rem;
    }}
    .quickstart {{
      margin: 0 0 1.5rem;
      padding: 1rem 1.1rem;
      border: 1px solid var(--line);
      border-left: .45rem solid var(--accent);
      background: rgba(255, 255, 255, .72);
      box-shadow: 0 1rem 2.5rem rgba(31, 37, 29, .06);
    }}
    .quickstart h2 {{
      margin: 0 0 .55rem;
      font-size: 1.05rem;
    }}
    .quickstart.warn {{
      border-left-color: var(--warn);
      background: #fff3ec;
    }}
    .quickstart.warn h2 {{
      color: var(--warn);
    }}
    .quickstart p {{
      margin: .4rem 0;
    }}
    .quickstart a {{
      color: var(--accent);
      font-weight: 700;
    }}
    table {{
      width: 100%;
      border-collapse: collapse;
      background: rgba(255, 255, 255, .76);
      border: 1px solid var(--line);
      box-shadow: 0 1.5rem 4rem rgba(31, 37, 29, .08);
    }}
    th, td {{
      padding: .85rem .9rem;
      border-bottom: 1px solid var(--line);
      text-align: left;
      vertical-align: top;
    }}
    th {{
      color: var(--muted);
      font-size: .78rem;
      letter-spacing: .08em;
      text-transform: uppercase;
    }}
    .open-link {{
      display: inline-block;
      border-radius: 999px;
      background: var(--accent);
      color: white;
      padding: .45rem .8rem;
      font-weight: 700;
      text-decoration: none;
      white-space: nowrap;
    }}
    .muted {{
      color: var(--muted);
    }}
    .task-note {{
      margin-top: .35rem;
      color: var(--ink);
      font-size: .9rem;
      overflow-wrap: anywhere;
    }}
    .files {{
      margin-top: 1rem;
      color: var(--muted);
      font-size: .92rem;
    }}
    .files a {{
      color: var(--accent);
      font-weight: 700;
    }}
    @media (max-width: 760px) {{
      main {{
        padding: 2rem 1rem;
      }}
      table {{
        display: block;
        overflow-x: auto;
      }}
    }}
  </style>
</head>
<body>
  <main>
    <h1>Your Palette labeling work</h1>
    <p class="meta">
      User: {_html_escape(user)}<br>
      Recordings: {_html_escape(manifest.get('counts', {}).get('recordings', 0) if isinstance(manifest.get('counts'), dict) else 0)}
      - Tasks: {_html_escape(manifest.get('counts', {}).get('tasks', 0) if isinstance(manifest.get('counts'), dict) else 0)}
      - Links: {_html_escape(manifest.get('counts', {}).get('signed_links', 0) if isinstance(manifest.get('counts'), dict) else 0)}
      - Link TTL: {_html_escape(manifest.get('ttl_seconds', ''))} seconds<br>
      Waiting recordings: {_html_escape(progress.get('waiting_recording_count', 0))}
      - Complete recordings: {_html_escape(progress.get('complete_recording_count', 0))}
      - Blocked/no-open recordings: {_html_escape(progress.get('blocked_recording_count', 0))}<br>
      Generated: {_html_escape(manifest.get('generated_at_utc', ''))}
      - Links expire: {_html_escape(manifest.get('links_expire_at_utc', ''))}
    </p>
    <section class="{quickstart_class}">
      <h2>{_html_escape(quickstart_heading)}</h2>
      {readiness_notice}
      <p>{_html_escape(start_guidance)}</p>
      {dataset_queue_state_notice}
      <p>Higher-priority tasks are listed first within each recording. Recording instructions appear in the Instructions column; task-specific notes appear under the relevant task.</p>
      {f'<p>{landing_entry}</p>' if landing_entry else ''}
      {f'<p>{labeling_home_entry}</p>' if labeling_home_entry else ''}
      {f'<p>{dataset_queue_entry}</p>' if dataset_queue_entry else ''}
      {f'<p>{canonical_dataset_queue_entry}</p>' if canonical_dataset_queue_entry else ''}
      <p>{dashboard_entry}</p>
      {f'<p>First open the identity check and confirm it reports you as <b>{_html_escape(user)}</b>: <a href="{_html_escape(identity_probe_url)}">{_html_escape(identity_probe_url)}</a></p>' if identity_probe_url else ''}
      <p>Before opening work, confirm the dashboard shows you as <b>{_html_escape(user)}</b>. If it shows another user, stop and contact the operator.</p>
      <p>Do not edit zarr files directly, forward this handoff, or share signed links. If access fails, the link expires, a task is missing, or this page only shows service-relative paths, ask the operator to regenerate your handoff with the service URL.</p>
      <p>Browser saves are applied server-side to your assigned task/training Zarr scope. CSV, HTML, JSON, and handoff files are metadata only and are not label write targets. Each recording has one active assigned owner, and only that current assignee can open or save browser labeling work. Labelers should not run operator evidence, repair, checksum, or validation commands; those commands are operator-only launch controls.</p>
      <p><a href="labeler-quickstart.txt">Read the text quickstart</a></p>
    </section>
    <table>
      <thead>
        <tr>
          <th>Recording</th>
          <th>Workflow</th>
          <th>Priority</th>
          <th>Task</th>
          <th>State</th>
          <th>Instructions</th>
          <th>Link</th>
        </tr>
      </thead>
      <tbody>
{generated_rows}
      </tbody>
    </table>
    <p class="files">
      Bundle files:
      <a href="work-summary.json">work-summary.json</a>,
      <a href="signed-links.jsonl">signed-links.jsonl</a>,
      <a href="check-store.json">check-store.json</a>,
      <a href="manifest.json">manifest.json</a>,
      <a href="labeler-quickstart.txt">labeler-quickstart.txt</a>,
      <a href="validation-log-template.md">validation-log-template.md</a>,
      <a href="validation-checklist.json">validation-checklist.json</a>
    </p>
  </main>
</body>
</html>
"""
    output_path.write_text(html, encoding="utf-8")


def _write_user_handoff_quickstart(
    *,
    user: str,
    manifest: dict[str, object],
    output_path: Path,
) -> None:
    counts = manifest.get("counts") if isinstance(manifest.get("counts"), dict) else {}
    base_url = str(manifest.get("base_url") or "").rstrip("/")
    landing_url = str(manifest.get("expected_user_labeler_landing_url") or manifest.get("labeler_landing_url") or base_url).strip()
    dashboard_url = str(manifest.get("expected_user_dashboard_url") or _dashboard_url_for_base(base_url))
    dataset_queue_url = str(manifest.get("expected_user_dataset_queue_url") or manifest.get("dataset_queue_url") or "").strip()
    labeling_home_url = str(
        manifest.get("expected_user_labeling_home_url")
        or manifest.get("labeling_home_url")
        or ""
    ).strip()
    personalized_entry_url = str(
        manifest.get("personalized_labeler_entry_url")
        or manifest.get("expected_user_personal_dataset_queue_url")
        or ""
    ).strip()
    identity_probe_url = str(manifest.get("expected_user_identity_probe_url") or "").strip()
    ready_to_send = bool(manifest.get("ready_to_send"))
    dataset_queue_state = (
        manifest.get("dataset_queue_state")
        if isinstance(manifest.get("dataset_queue_state"), Mapping)
        else {}
    )
    dataset_queue_state_code = str(dataset_queue_state.get("code") or "")
    dataset_queue_state_title = str(dataset_queue_state.get("title") or "")
    dataset_queue_state_message = str(dataset_queue_state.get("message") or "")
    dataset_queue_operator_action = str(dataset_queue_state.get("operator_action") or "")
    dataset_queue_blocks_start = bool(dataset_queue_state.get("blocks_labeler_start"))
    warning_reasons: list[str] = []
    warnings = manifest.get("sendability_warnings")
    if isinstance(warnings, list):
        for warning in warnings:
            if not isinstance(warning, Mapping):
                continue
            reasons = warning.get("reasons")
            if not isinstance(reasons, list):
                continue
            for reason in reasons:
                reason_text = str(reason or "").strip()
                if reason_text and reason_text not in warning_reasons:
                    warning_reasons.append(reason_text)
    sendability_actions = [
        str(action).strip()
        for action in (manifest.get("sendability_actions") if isinstance(manifest.get("sendability_actions"), list) else [])
        if str(action).strip()
    ]
    lines = [
        "Palette labeling quickstart",
        "",
        f"User: {user}",
        f"Recordings: {counts.get('recordings', 0)}",
        f"Tasks: {counts.get('tasks', 0)}",
        f"Signed links: {counts.get('signed_links', 0)}",
        f"Generated at UTC: {manifest.get('generated_at_utc', '')}",
        f"Links expire at UTC: {manifest.get('links_expire_at_utc', '')}",
        "",
        "No Palette or Crimson installation is needed for this browser workflow.",
        "",
        "Readiness:",
        "This handoff is ready to use." if ready_to_send else "Wait for operator review before starting.",
        f"Review reasons: {', '.join(warning_reasons) if warning_reasons else 'none' if ready_to_send else 'operator_review_required'}",
        f"Dataset queue state: {dataset_queue_state_code or 'unknown'}{(' - ' + dataset_queue_state_title) if dataset_queue_state_title else ''}",
        f"Dataset queue start: {'blocked' if dataset_queue_blocks_start else 'allowed'}",
    ]
    if dataset_queue_state_message:
        lines.append(f"Dataset queue message: {dataset_queue_state_message}")
    if dataset_queue_operator_action:
        lines.append(f"Dataset queue operator action: {dataset_queue_operator_action}")
    if dataset_queue_blocks_start:
        lines.append("Do not start new labeling from the dataset queue until the operator resolves this state.")
    if sendability_actions:
        lines.extend(["Repair actions:", *[f"- {action}" for action in sendability_actions]])
    lines.extend(
        [
            "",
            "How to start:" if ready_to_send else "How to preview while waiting:",
        ]
    )
    if dashboard_url:
        queue_start_url = personalized_entry_url or dataset_queue_url or dashboard_url
        if ready_to_send:
            lines.extend(
                [
                    f"1. Open the identity check and confirm it reports you as {user}: {identity_probe_url or '(operator did not provide an identity probe URL)'}",
                    f"2. Open your datasets-waiting landing page: {landing_url or dataset_queue_url or dashboard_url}",
                    f"3. Human-readable labeling home alias: {labeling_home_url or landing_url or dataset_queue_url or dashboard_url}",
                    f"4. Open your personalized dataset queue as the preferred queue-first view: {queue_start_url}",
                    f"5. Canonical dataset queue fallback: {dataset_queue_url or dashboard_url}",
                    f"6. Open your full dashboard when you need the fallback view: {dashboard_url}",
                    f"7. Confirm the dashboard shows you as {user}; if it shows another user, stop and contact the operator.",
                    "8. Open one assigned task at a time and save through the browser controls.",
                    "9. Browser saves are applied server-side to your assigned task/training Zarr scope; CSV, HTML, JSON, and handoff files are metadata only.",
                    "10. Each recording has one active assigned owner, and only that current assignee can open or save browser labeling work.",
                    "11. Labelers should not run operator evidence, repair, checksum, or validation commands; those commands are operator-only launch controls.",
                ]
            )
        else:
            lines.extend(
                [
                    "1. Open index.html from this handoff directory to preview your assigned work.",
                    "2. Do not open or save task work until the operator confirms this handoff is ready.",
                    f"3. Open the identity check and confirm it reports you as {user}: {identity_probe_url or '(operator did not provide an identity probe URL)'}",
                    f"4. Open your datasets-waiting landing page: {landing_url or dataset_queue_url or dashboard_url}",
                    f"5. Human-readable labeling home alias: {labeling_home_url or landing_url or dataset_queue_url or dashboard_url}",
                    f"6. Then use your personalized dataset queue as the preferred queue-first view or dashboard. Confirm the dashboard shows you as {user}: {queue_start_url}",
                    f"7. Open your full dashboard preview when needed: {dashboard_url}",
                    f"8. Canonical dataset queue fallback: {dataset_queue_url or dashboard_url}",
                ]
            )
    else:
        lines.extend(
            [
                "1. Open index.html from this handoff directory to preview your assigned work.",
                "2. Ask the operator for the service dashboard URL before opening tasks.",
                f"3. If the operator gives you a service URL, confirm the dashboard shows you as {user} before opening work.",
            ]
        )
    lines.extend(
        [
            "",
            "Safety rules:",
            "- Do not edit zarr files directly.",
            "- Browser saves are applied server-side to your assigned task/training Zarr scope.",
            "- CSV, HTML, JSON, and handoff files are metadata only and are not label write targets.",
            "- Each recording has one active assigned owner, and only that current assignee can open or save browser labeling work.",
            "- Labelers should not run operator evidence, repair, checksum, or validation commands; those commands are operator-only launch controls.",
            "- Do not forward this handoff or signed links to another user.",
            "- Do not keep working after the operator says a recording was reassigned or paused.",
            "- Stop before opening work if the dashboard shows a different signed-in user.",
            "- Use the task completion controls only after the assigned review/edit is finished.",
            "",
            "Ask the operator for help if:",
            "- the dashboard does not show the expected recording",
            "- a signed link is expired",
            "- the handoff was generated without a service URL",
            "- a task is missing",
            "- saving fails",
            "- the browser shows another user's work",
            "",
        ]
    )
    output_path.write_text("\n".join(lines), encoding="utf-8")


def _write_user_handoff_message(
    *,
    user: str,
    manifest: dict[str, object],
    output_path: Path,
) -> None:
    counts = manifest.get("counts") if isinstance(manifest.get("counts"), dict) else {}
    base_url = str(manifest.get("base_url") or "").rstrip("/")
    landing_url = str(manifest.get("expected_user_labeler_landing_url") or manifest.get("labeler_landing_url") or base_url).strip() or None
    dashboard_url = str(manifest.get("expected_user_dashboard_url") or _dashboard_url_for_base(base_url)).strip() or None
    dataset_queue_url = str(manifest.get("expected_user_dataset_queue_url") or manifest.get("dataset_queue_url") or "").strip() or None
    labeling_home_url = (
        str(
            manifest.get("expected_user_labeling_home_url")
            or manifest.get("labeling_home_url")
            or ""
        ).strip()
        or None
    )
    personalized_entry_url = (
        str(
            manifest.get("personalized_labeler_entry_url")
            or manifest.get("expected_user_personal_dataset_queue_url")
            or ""
        ).strip()
        or None
    )
    identity_probe_url = str(manifest.get("expected_user_identity_probe_url") or "").strip() or None
    ready_to_send = bool(manifest.get("ready_to_send"))
    dataset_queue_state = (
        manifest.get("dataset_queue_state")
        if isinstance(manifest.get("dataset_queue_state"), Mapping)
        else {}
    )
    dataset_queue_state_code = str(dataset_queue_state.get("code") or "")
    dataset_queue_state_title = str(dataset_queue_state.get("title") or "")
    dataset_queue_state_message = str(dataset_queue_state.get("message") or "")
    dataset_queue_operator_action = str(dataset_queue_state.get("operator_action") or "")
    dataset_queue_blocks_start = bool(dataset_queue_state.get("blocks_labeler_start"))
    warning_reasons: list[str] = []
    warnings = manifest.get("sendability_warnings")
    if isinstance(warnings, list):
        for warning in warnings:
            if not isinstance(warning, Mapping):
                continue
            reasons = warning.get("reasons")
            if not isinstance(reasons, list):
                continue
            for reason in reasons:
                reason_text = str(reason or "").strip()
                if reason_text and reason_text not in warning_reasons:
                    warning_reasons.append(reason_text)
    sendability_actions = [
        str(action).strip()
        for action in (manifest.get("sendability_actions") if isinstance(manifest.get("sendability_actions"), list) else [])
        if str(action).strip()
    ]
    lines = [
        "Your Palette labeling work is ready."
        if ready_to_send
        else "Your Palette labeling handoff needs operator review before starting.",
        "",
        f"User: {user}",
        f"Recordings: {counts.get('recordings', 0)}",
        f"Tasks: {counts.get('tasks', 0)}",
        f"Signed links: {counts.get('signed_links', 0)}",
        f"Link TTL seconds: {manifest.get('ttl_seconds', '')}",
        f"Generated at UTC: {manifest.get('generated_at_utc', '')}",
        f"Links expire at UTC: {manifest.get('links_expire_at_utc', '')}",
        "",
        "No Palette or Crimson installation is needed for this browser workflow.",
        "Read labeler-quickstart.txt before starting.",
        f"Dataset queue state: {dataset_queue_state_code or 'unknown'}{(' - ' + dataset_queue_state_title) if dataset_queue_state_title else ''}",
        f"Dataset queue start: {'blocked' if dataset_queue_blocks_start else 'allowed'}",
        "",
    ]
    if dataset_queue_state_message:
        lines.extend(["Dataset queue message:", dataset_queue_state_message, ""])
    if dataset_queue_operator_action:
        lines.extend(["Dataset queue operator action:", dataset_queue_operator_action, ""])
    if dataset_queue_blocks_start:
        lines.extend(
            [
                "Do not start new labeling from the dataset queue until the operator resolves this state.",
                "",
            ]
        )
    if not ready_to_send:
        lines.extend(
            [
                "Do not start labeling from this handoff until the operator confirms it is ready.",
                f"Review reasons: {', '.join(warning_reasons) if warning_reasons else 'operator_review_required'}",
                *(
                    ["Repair actions:", *[f"- {action}" for action in sendability_actions]]
                    if sendability_actions
                    else []
                ),
                "",
            ]
        )
    if dashboard_url:
        queue_start_url = personalized_entry_url or dataset_queue_url or landing_url or dashboard_url
        lines.extend(
            [
                "Identity check:",
                identity_probe_url or "(operator did not provide an identity probe URL)",
                f"Open this first and confirm it reports you as {user} before labeling.",
                "",
                "Preferred queue-first entry point:" if ready_to_send else "Preview queue-first entry point:",
                queue_start_url or "(operator did not provide a dataset queue URL)",
                "",
                "Start here:",
                queue_start_url or "(operator did not provide a dataset queue URL)",
                "",
                "Queue-first start page:",
                landing_url or dataset_queue_url or dashboard_url or "(operator did not provide a landing URL)",
                "",
                "Human-readable labeling home alias:",
                labeling_home_url or landing_url or dataset_queue_url or dashboard_url or "(operator did not provide a labeling home URL)",
                "",
                "Personalized dataset queue:",
                personalized_entry_url or dataset_queue_url or dashboard_url or "(operator did not provide a dataset queue URL)",
                "",
                "Canonical dataset queue fallback:",
                dataset_queue_url or dashboard_url or "(operator did not provide a dataset queue URL)",
                "",
                "Full dashboard fallback:" if ready_to_send else "Preview dashboard:",
                dashboard_url,
                f"Before opening work, confirm the dashboard shows you as {user}. If it shows another user, stop and contact the operator.",
                "",
            ]
        )
    else:
        lines.extend(
            [
                "This handoff was generated without a service base URL.",
                "Open index.html to preview your work, then ask the operator for the service dashboard URL before opening tasks.",
                f"Before opening work from any service URL, confirm the dashboard shows you as {user}. If it shows another user, stop and contact the operator.",
                "",
            ]
        )
    lines.extend(
        [
            "If you were given this handoff bundle, open index.html in this directory.",
            "The included task links are convenience entry points and still require authenticated access.",
            "Do not edit zarr files directly or forward this handoff to another user.",
            "Browser saves are applied server-side to your assigned task/training Zarr scope; CSV, HTML, JSON, and handoff files are metadata only. "
            "Each recording has one active assigned owner, and only that current assignee can open or save browser labeling work.",
            "Labelers should not run operator evidence, repair, checksum, or validation commands; those commands are operator-only launch controls.",
            "If a link is expired or a task is missing, ask the operator to regenerate your handoff.",
            "",
        ]
    )
    output_path.write_text("\n".join(lines), encoding="utf-8")


def _batch_readiness_report(store: LabelingStore) -> dict[str, object]:
    assignments = store.list_assignments(status=None)
    tasks = store.list_tasks(include_completed=True)
    active_sessions = store.list_sessions(include_closed=False, limit=10000)
    consistency = _store_consistency_report(store)
    active_assignments = [
        assignment
        for assignment in assignments
        if str(assignment.get("status") or "") == "active"
    ]
    active_recording_ids = {
        str(assignment.get("recording_id") or "")
        for assignment in active_assignments
        if str(assignment.get("recording_id") or "")
    }
    tasks_by_recording: dict[str, list[dict[str, object]]] = {}
    users: dict[str, dict[str, object]] = {}
    open_task_count = 0
    completed_task_count = 0
    active_open_task_count = 0
    active_completed_task_count = 0
    active_recordings_without_tasks_count = 0
    active_recordings_without_open_tasks_count = 0
    active_recordings_without_open_tasks_by_reason: dict[str, int] = {}
    active_users_without_open_tasks_count = 0

    for assignment in active_assignments:
        user = str(assignment.get("assignee_user") or "").strip()
        if not user:
            continue
        users.setdefault(
            user,
            {
                "user": user,
                "active_recordings": 0,
                "open_tasks": 0,
                "completed_tasks": 0,
                "total_tasks": 0,
            },
        )
        users[user]["active_recordings"] = int(users[user]["active_recordings"]) + 1

    for task in tasks:
        recording_id = str(task.get("recording_id") or "")
        tasks_by_recording.setdefault(recording_id, []).append(task)
        state = str(task.get("state") or "")
        startable = state in LABELER_START_TASK_STATES
        assignment_status = str(task.get("assignment_status") or "")
        assignee_user = str(task.get("assignee_user") or "").strip()
        if state == "complete":
            completed_task_count += 1
        elif startable:
            open_task_count += 1
        if assignment_status != "active" or not assignee_user:
            continue
        if state == "complete":
            active_completed_task_count += 1
        elif startable:
            active_open_task_count += 1
        row = users.setdefault(
            assignee_user,
            {
                "user": assignee_user,
                "active_recordings": 0,
                "open_tasks": 0,
                "completed_tasks": 0,
                "total_tasks": 0,
            },
        )
        row["total_tasks"] = int(row["total_tasks"]) + 1
        if state == "complete":
            row["completed_tasks"] = int(row["completed_tasks"]) + 1
        elif startable:
            row["open_tasks"] = int(row["open_tasks"]) + 1

    readiness_issues: list[dict[str, object]] = []
    readiness_warnings: list[dict[str, object]] = []
    if not active_assignments:
        readiness_issues.append(
            {
                "code": "no_active_assignments",
                "details": "No active recording assignments are available for labelers.",
            }
        )
    if active_open_task_count == 0:
        readiness_issues.append(
            {
                "code": "no_open_tasks",
                "details": "No startable tasks under active assignments are available for labelers.",
            }
        )

    for assignment in active_assignments:
        recording_id = str(assignment.get("recording_id") or "")
        recording_tasks = tasks_by_recording.get(recording_id, [])
        open_recording_tasks = [
            task
            for task in recording_tasks
            if str(task.get("state") or "") in LABELER_START_TASK_STATES
        ]
        if not recording_tasks:
            active_recordings_without_tasks_count += 1
            active_recordings_without_open_tasks_count += 1
            reason = "tasks_not_generated"
            active_recordings_without_open_tasks_by_reason[reason] = (
                active_recordings_without_open_tasks_by_reason.get(reason, 0) + 1
            )
            readiness_warnings.append(
                {
                    "code": "active_assignment_without_tasks",
                    "no_open_task_reason": reason,
                    "no_open_task_actions": _recordings_without_open_tasks_actions([reason]),
                    "recording_id": recording_id,
                    "assignee_user": assignment.get("assignee_user"),
                    "details": "Recording is actively assigned but has no labeling tasks.",
                }
            )
        elif not open_recording_tasks:
            active_recordings_without_open_tasks_count += 1
            reason = (
                "all_tasks_complete"
                if all(str(task.get("state") or "") == "complete" for task in recording_tasks)
                else "non_startable_task_state"
            )
            active_recordings_without_open_tasks_by_reason[reason] = (
                active_recordings_without_open_tasks_by_reason.get(reason, 0) + 1
            )
            readiness_warnings.append(
                {
                    "code": "active_assignment_without_open_tasks",
                    "no_open_task_reason": reason,
                    "no_open_task_actions": _recordings_without_open_tasks_actions([reason]),
                    "recording_id": recording_id,
                    "assignee_user": assignment.get("assignee_user"),
                    "details": "Recording is actively assigned but no tasks are in a startable labeling state.",
                }
            )

    for row in users.values():
        if int(row.get("open_tasks") or 0) == 0:
            active_users_without_open_tasks_count += 1
            readiness_warnings.append(
                {
                    "code": "active_user_without_open_tasks",
                    "assignee_user": row.get("user"),
                    "details": "User has active recording assignments but no startable tasks.",
                }
            )

    return {
        "ok": bool(consistency["ok"]) and not readiness_issues,
        "checked_at_utc": datetime.now(timezone.utc).isoformat(),
        "single_owner_policy": _assignment_ownership_policy(),
        "assignment_ownership_integrity": consistency.get("assignment_ownership_integrity", {}),
        "counts": {
            "assignments": len(assignments),
            "active_assignments": len(active_assignments),
            "inactive_assignments": len(assignments) - len(active_assignments),
            "active_recordings": len(active_recording_ids),
            "active_users": len(users),
            "active_recordings_without_tasks": active_recordings_without_tasks_count,
            "active_recordings_without_open_tasks": active_recordings_without_open_tasks_count,
            "active_recordings_without_open_tasks_by_reason": dict(
                sorted(active_recordings_without_open_tasks_by_reason.items())
            ),
            "active_recordings_without_open_tasks_actions": _recordings_without_open_tasks_actions(
                active_recordings_without_open_tasks_by_reason
            ),
            "active_users_without_open_tasks": active_users_without_open_tasks_count,
            "tasks": len(tasks),
            "open_tasks": open_task_count,
            "completed_tasks": completed_task_count,
            "active_open_tasks": active_open_task_count,
            "active_completed_tasks": active_completed_task_count,
            "active_sessions": len(active_sessions),
        },
        "readiness_issue_count": len(readiness_issues),
        "readiness_warning_count": len(readiness_warnings),
        "readiness_issues": readiness_issues,
        "readiness_warnings": readiness_warnings,
        "store_consistency": consistency,
        "users": sorted(users.values(), key=lambda row: str(row.get("user") or "")),
    }


def _apply_readiness_warning_policy(report: dict[str, object], *, warnings_as_errors: bool) -> dict[str, object]:
    readiness_warning_count = int(report.get("readiness_warning_count") or 0)
    store_consistency = report.get("store_consistency") if isinstance(report.get("store_consistency"), dict) else {}
    store_warning_count = int(store_consistency.get("warning_count") or 0)
    total_warning_count = readiness_warning_count + store_warning_count
    readiness_warning_codes = [
        str(row.get("code") or "")
        for row in report.get("readiness_warnings", [])
        if isinstance(row, dict) and str(row.get("code") or "")
    ]
    store_warning_codes = [
        str(row.get("code") or "")
        for row in store_consistency.get("warnings", [])
        if isinstance(row, dict) and str(row.get("code") or "")
    ]
    report["warnings_as_errors"] = bool(warnings_as_errors)
    report["warning_count"] = total_warning_count
    report["blocking_warning_count"] = total_warning_count if warnings_as_errors else 0
    report["blocking_warning_codes"] = sorted(set(readiness_warning_codes + store_warning_codes)) if warnings_as_errors else []
    if warnings_as_errors and total_warning_count:
        report["ok"] = False
    return report


def _write_user_handoff_bundle(
    *,
    store: LabelingStore,
    store_path: Path,
    user: str,
    output_dir: Path,
    secret: str,
    base_url: str | None,
    ttl_seconds: int,
    include_completed: bool,
    overwrite: bool,
    zip_output: Path | None = None,
) -> dict[str, object]:
    if zip_output is not None:
        _check_directory_zip_output(output_dir, zip_output, overwrite=overwrite)
    output_dir.mkdir(parents=True, exist_ok=True)
    handoff_paths = _user_handoff_paths(output_dir)
    existing_paths = [path for path in handoff_paths.values() if path.exists()]
    if zip_output is not None and zip_output.exists():
        existing_paths.append(zip_output)
    if existing_paths and not overwrite:
        raise FileExistsError(
            "Refusing to overwrite existing user handoff files: "
            + ", ".join(str(path) for path in existing_paths)
        )

    normalized_user = str(user)
    normalized_base_url = str(base_url or "").rstrip("/")
    generated_at_utc = datetime.now(timezone.utc).isoformat()
    link_issued_at_utc: list[str] = []
    link_expires_at_utc: list[str] = []
    check_report = _store_consistency_report(store)
    work = store.task_summary_for_user(normalized_user, include_completed=include_completed)
    work["include_completed"] = include_completed
    _add_work_summary_fields(
        work,
        reassignment_session_safety=check_report.get("reassignment_session_safety", {}),
    )
    work["browser_mutation_write_policy"] = _browser_mutation_write_policy()
    work["browser_mutation_write_checklist"] = _browser_mutation_write_runtime_checklist()
    work["dataset_queue_direct_start_policy"] = _dataset_queue_direct_start_policy()
    work["runtime_operator_validation_gate_cli_policy"] = _runtime_operator_validation_gate_cli_policy()
    work["single_owner_policy"] = _assignment_ownership_policy()
    work["assignment_ownership_integrity"] = check_report.get(
        "assignment_ownership_integrity",
        {},
    )
    single_owner_assignment_contract = store.single_owner_assignment_contract()
    work["single_owner_assignment_contract"] = single_owner_assignment_contract
    _add_payload_contract_compact_fields(work)
    _add_direct_start_contracts_to_work_tasks(
        work,
        expected_user=normalized_user,
        reassignment_session_safety=check_report.get("reassignment_session_safety", {}),
    )
    tasks = [
        task
        for task in store.list_tasks(
            assignee_user=normalized_user,
            include_completed=include_completed,
        )
        if str(task.get("assignment_status") or "") == "active"
    ]
    links: list[dict[str, object]] = []
    for task in tasks:
        task_id = str(task["task_id"])
        row_warnings: list[dict[str, object]] = []
        if not normalized_base_url:
            row_warnings.append(
                {
                    "code": "missing_base_url",
                    "details": "Generated URL is service-relative. Regenerate the handoff with --base-url before sharing with a labeler.",
                }
            )
        if str(task.get("state") or "") == "complete":
            row_warnings.append(
                {
                    "code": "task_completed",
                    "task_id": task_id,
                    "recording_id": task.get("recording_id"),
                    "details": "Task is complete, so the signed link will not open a new labeling session unless the task is reopened.",
                }
            )
        elif str(task.get("state") or "") not in LABELER_START_TASK_STATES:
            row_warnings.append(
                {
                    "code": "task_not_startable",
                    "task_id": task_id,
                    "recording_id": task.get("recording_id"),
                    "state": task.get("state"),
                    "startable_task_states": list(LABELER_START_TASK_STATES),
                    "details": "Task is not in a startable labeling state, so the signed link will not open a new labeling session.",
                }
            )
        token_info = _signed_task_link_token_info(
            task_id=task_id,
            secret=secret,
            ttl_seconds=ttl_seconds,
            expected_user=str(task.get("assignee_user") or ""),
        )
        token = str(token_info["token"])
        link_issued_at_utc.append(str(token_info["issued_at_utc"]))
        link_expires_at_utc.append(str(token_info["expires_at_utc"]))
        path = f"/t/{token}"
        links.append(
            {
                "task_id": task_id,
                "recording_id": task.get("recording_id"),
                "assignee_user": task.get("assignee_user"),
                "expected_user": token_info.get("expected_user") or task.get("assignee_user"),
                "workflow_kind": task.get("workflow_kind"),
                "state": task.get("state"),
                "startable_task_states": list(LABELER_START_TASK_STATES),
                "title": task.get("title"),
                "issued_at_utc": token_info["issued_at_utc"],
                "expires_in_seconds": token_info["ttl_seconds"],
                "expires_at_utc": token_info["expires_at_utc"],
                "path": path,
                "url": f"{normalized_base_url}{path}" if normalized_base_url else path,
                "url_is_absolute": bool(normalized_base_url),
                "task_launchable": not any(
                    str(warning.get("code") or "").startswith("task_")
                    for warning in row_warnings
                ),
                "ready_to_share": bool(normalized_base_url) and not row_warnings,
                "shareability_warnings": row_warnings,
            }
        )
    if link_issued_at_utc:
        generated_at_utc = min(link_issued_at_utc)
    links_expire_at_utc = min(link_expires_at_utc) if link_expires_at_utc else None
    known_user_status = _known_labeler_status(store, normalized_user)
    labeler_route_authorization_policy = _labeler_route_authorization_policy()
    assignment_ownership_integrity = _assignment_ownership_integrity(
        store.list_assignments(status=None),
        schema_integrity=store.assignment_schema_integrity(),
    )
    assignment_ownership_contract = _assignment_ownership_contract_policy(
        _assignment_ownership_policy(),
        assignment_ownership_integrity,
        store_single_owner_contract=single_owner_assignment_contract,
    )
    work["single_owner_assignment_contract"] = single_owner_assignment_contract
    work["assignment_ownership_contract"] = assignment_ownership_contract
    work.update(_assignment_ownership_contract_fields(assignment_ownership_contract))
    work["single_owner_policy_contract_met"] = bool(
        assignment_ownership_contract.get("ready")
    ) and int(assignment_ownership_integrity.get("duplicate_active_owner_count") or 0) == 0
    labeler_route_authorization_checklist = _labeler_route_authorization_runtime_checklist(
        policy=labeler_route_authorization_policy,
        user=normalized_user,
        expected_user=normalized_user,
        known_user_status=known_user_status,
        assignment_ownership_contract=assignment_ownership_contract,
    )
    work["labeler_route_authorization_policy"] = labeler_route_authorization_policy
    work["labeler_route_authorization_checklist"] = labeler_route_authorization_checklist
    operator_validation_visibility_policy = _operator_validation_visibility_policy()
    initial_operator_validation_public_fields = _operator_validation_public_fields(
        _dashboard_operator_validation_fields()
    )
    initial_safe_share_gate = _safe_share_gate_policy()
    initial_safe_share_fields = _safe_share_gate_flat_fields(initial_safe_share_gate)
    initial_safe_share_checklist_fields = _safe_share_checklist_gate_status_fields_from_operator_validation(
        initial_operator_validation_public_fields,
        safe_share_gate=initial_safe_share_gate,
    )
    initial_operator_validation_command_templates = _operator_validation_command_templates(
        initial_operator_validation_public_fields.get(
            "operator_validation_required_missing_evidence_gate_ids"
        )
        if isinstance(
            initial_operator_validation_public_fields.get(
                "operator_validation_required_missing_evidence_gate_ids"
            ),
            list,
        )
        else None
    )
    work.update(initial_operator_validation_public_fields)
    work["safe_share_gate"] = initial_safe_share_gate
    work.update(initial_safe_share_fields)
    work.update(initial_safe_share_checklist_fields)
    work["operator_validation_command_templates"] = initial_operator_validation_command_templates
    work["operator_validation_visibility_policy"] = operator_validation_visibility_policy
    public_reassignment_session_safety = (
        work.get("reassignment_session_safety")
        if isinstance(work.get("reassignment_session_safety"), Mapping)
        else _public_reassignment_session_safety_fields(
            check_report.get("reassignment_session_safety", {}),
            recording_ids=_work_recording_ids(work),
        )
    )
    work["reassignment_session_safety"] = public_reassignment_session_safety
    work_payload = {
        "ok": True,
        "store_path": str(store_path),
        "include_completed": include_completed,
        "known_user_status": known_user_status,
        "labeler_route_authorization_policy": labeler_route_authorization_policy,
        "labeler_route_authorization_checklist": labeler_route_authorization_checklist,
        "operator_validation_visibility_policy": operator_validation_visibility_policy,
        "operator_validation_command_templates": initial_operator_validation_command_templates,
        "labeler_work_completion": work.get("labeler_work_completion", {}),
        **_labeler_work_completion_fields(
            work.get("labeler_work_completion")
            if isinstance(work.get("labeler_work_completion"), Mapping)
            else None
        ),
        "task_state_policy": _browser_task_state_policy(),
        "zarr_backup_policy": _zarr_backup_policy(),
        "mutation_audit_policy": _mutation_audit_policy(),
        "browser_mutation_write_policy": _browser_mutation_write_policy(),
        "browser_mutation_write_checklist": _browser_mutation_write_runtime_checklist(),
        "dataset_queue_direct_start_policy": _dataset_queue_direct_start_policy(),
        "runtime_operator_validation_gate_cli_policy": _runtime_operator_validation_gate_cli_policy(),
        "single_owner_policy": _assignment_ownership_policy(),
        "single_owner_assignment_contract": single_owner_assignment_contract,
        "assignment_ownership_integrity": check_report.get(
            "assignment_ownership_integrity",
            {},
        ),
        "safe_share_gate": initial_safe_share_gate,
        **initial_safe_share_fields,
        **initial_safe_share_checklist_fields,
        "reassignment_session_safety": public_reassignment_session_safety,
        **_reassignment_session_safety_flat_fields(public_reassignment_session_safety),
        "browser_response_security_policy": _browser_response_security_policy(),
        "session_guard_policy": _session_guard_policy(),
        "signed_link_policy": _browser_signed_link_policy(),
        "browser_workflows": _browser_workflow_capabilities(),
        **initial_operator_validation_public_fields,
        "work": work,
    }
    _add_payload_contract_compact_fields(work_payload)
    handoff_paths["work_summary"].write_text(
        json.dumps(work_payload, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    handoff_paths["signed_links"].write_text(
        "".join(json.dumps(link, sort_keys=True) + "\n" for link in links),
        encoding="utf-8",
    )
    handoff_paths["store_check"].write_text(
        json.dumps({"store_path": str(store_path), **check_report}, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    manifest_files = {key: str(path) for key, path in handoff_paths.items()}
    if zip_output is not None:
        manifest_files["bundle_zip"] = str(zip_output)
    no_open_by_reason = _count_recordings_without_open_tasks_by_reason(work)
    labeler_landing_url = _labeler_landing_url_for_base(normalized_base_url)
    labeling_home_url = _labeling_home_url_for_base(normalized_base_url)
    dashboard_url = _dashboard_url_for_base(normalized_base_url)
    dataset_queue_url = _dataset_queue_url_for_base(normalized_base_url)
    personal_work_url = (
        f"{str(normalized_base_url).rstrip('/')}{PERSONAL_WORK_PATH}"
        if normalized_base_url
        else ""
    )
    personal_dataset_queue_url = (
        f"{str(normalized_base_url).rstrip('/')}{PERSONAL_DATASET_QUEUE_PATH}"
        if normalized_base_url
        else ""
    )
    expected_user_labeler_landing_url = _dashboard_url_for_expected_user(labeler_landing_url, normalized_user)
    expected_user_labeling_home_url = _dashboard_url_for_expected_user(labeling_home_url, normalized_user)
    expected_user_dashboard_url = _dashboard_url_for_expected_user(dashboard_url, normalized_user)
    expected_user_dataset_queue_url = _dashboard_url_for_expected_user(dataset_queue_url, normalized_user)
    expected_user_personal_work_url = _dashboard_url_for_expected_user(
        personal_work_url,
        normalized_user,
    )
    expected_user_personal_dataset_queue_url = _dashboard_url_for_expected_user(
        personal_dataset_queue_url,
        normalized_user,
    )
    expected_user_identity_probe_url = _dashboard_url_for_expected_user(
        _identity_probe_url_for_base(normalized_base_url),
        normalized_user,
    )
    work["personal_work_page_path"] = PERSONAL_WORK_PATH
    work["labeling_home_page_path"] = LABELING_HOME_PATH
    work["personal_dataset_queue_page_path"] = PERSONAL_DATASET_QUEUE_PATH
    work["expected_user_labeling_home_url"] = expected_user_labeling_home_url
    work["expected_user_personal_work_url"] = expected_user_personal_work_url
    work["expected_user_personal_dataset_queue_url"] = expected_user_personal_dataset_queue_url
